from fractions import Fraction

def optimal_game_play(N, M, A, B):
    # If the modulus is zero, all elements are divisible by B_i
    if B[0] == 0:
        min_sum_A = sum(A)
    # Otherwise, the first player can either remove all divisible elements or none
    else:
        min_sum_A = sum(A) * Fraction(1, 1)

    for i in range(1, M):
        if B[i] > 0:
            # The second player can either remove all divisible by current B_i or none
            min_sum_A *= Fraction(1 - 1/B[i-1], 1 - 1/B[i])

    return int(min_sum_A)

