from collections import defaultdict

def solve(military_man, orders, ranks, x, y):
    visited = set()
    stacks = []
    for i in range(len(military_man)):
        rank = ranks[i]
        if not military_man[i] and i < y:
            return []
        if not visited and y < i:
            visited[i] = True
            stacks.append(i)
        count = 0
        while stacks and count < x:
            current = stacks.pop()
            if current == y:
                break
            for next in orders[current]:
                if next not in visited and ranks[next] == rank + 1:
                    visited[next] = True
                    stacks.append(next)
                if next >= i and ranks[next] >= rank:
                    count += 1
        if not visited[i]:
            return []
    if x < y:
        return []
    return ranks

def assign_ranks(military_man, orders, ranks, n, m):
    for i in range(1, len(ranks) + 1):
        new_ranks = defaultdict(lambda : ranks[0])
        for j in range(m):
            military_man_loc, rank_loc = orders[j]
            ranks_loc = orders[j][1]
            new_ranks[military_man_loc] = max(new_ranks[military_man_loc], i)
            ranks_loc = new_ranks[ranks_loc]
            if i >= ranks_loc:
                return [-1]
            ranks_loc += 1
        ranks = new_ranks
    return list(ranks.values())

def solve_forever(military_man, orders, ranks, x, y):
    ranks = []
    for i in range(1, 2 * len(ranks) + 1):
        new_rank = solve(military_man, orders, ranks, x, y)
        if new_rank in [-1] or all(rank < x for rank in new_rank):
            return [False] + [i - len(ranks)] * len(new_rank)
        else:
            ranks.extend(new_rank[1:])
    return ranks

