from typing import List, Tuple

def find_ancestor(node: int, parent_map: Dict[int, int], indices: List[int]) -> int:
    parent = node
    while parent != indices[parent-1]:
        parent = indices[parent-1]
    while parent_map[parent] != parent:
        parent = parent_map[parent]
    return parent + 1

def bad_edges(tree1: List[int], tree2: List[int]) -> List[Tuple[List[int], int]]:
    subtree_indices = {}
    for i in range(len(tree1)):
        subtree_indices[i+1] = i
    merged_indices = []
    dummy_index = len(subtree_indices) + 1
    stack = [(0, dummy_index)]
    while stack:
        parent_index, dummy_index = stack.pop()
        if parent_index not in subtree_indices:
            subtree_indices[parent_index] = dummy_index
            merged_indices.append((parent_index, tuple(), dummy_index))
            dummy_index += 1
        for child_index in tree1:
            if child_index == parent_index:
                continue
            if child_index not in subtree_indices:
                subtree_indices[child_index] = dummy_index
                merged_indices.append((child_index, tuple(), dummy_index))
                dummy_index += 1
            stack.append((child_index, dummy_index))
    tree1.sort(key=lambda i: indices[i-1])
    tree2.sort(key=lambda i: indices[i-1])
    blue_edges = []
    stack = []
    for i in range(len(tree1)):
        if tree1[i] == tree2[i]:
            continue
        if tree1[i] < tree2[i]:
            edge = (tree1[i], tree2[i])
        elif tree1[i] > tree2[i]:
            edge = (tree2[i], tree1[i])
        stack.append(edge)
    for edge in stack:
        parent = find_ancestor(edge[0], subtree_indices, tree1)
        child = find_ancestor(edge[1], subtree_indices, tree1)
        if subtree_indices[parent] < subtree_indices[child]:
            child = edge[0], edge[1]
        bad_edges.append((edge, subtree_indices[find_ancestor(edge[0], subtree_indices, tree1)]))
    return bad_edges

