from collections import defaultdict

def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

def find_min_operations(arr, N):
    dp = defaultdict(list)
    for i in range(N-1, -1, -1):
        for j in range(N, i+1):
            if gcd(arr[i], arr[j-1]) == 1:
                dp[i].append(j-1)
    if not dp:
        return -1, []

    result = float('inf')
    min_ops = None
    for i in sorted(dp.keys()):
        if result == i:
            min_ops = sorted(dp[i])
            break
        if result < i:
            break
        prev_ops = dp.get(i-1, [])
        if prev_ops:
            if i - 1 in prev_ops:
                min_ops = sorted(dp[i])
                break
            min_ops = dp[i] + prev_ops

    return len(min_ops), min_ops

