def simulate_bakery(n, m, q, table):
    position = (0, 0)
    queue = [(position)]
    visited = {position}

    while queue:
        position = queue.pop(0)
        x, y = position

        # Check if the bread is stuck infinitely looping
        if y >= m:
            return -1

        # Get the new direction
        if table[x][y] == ">": 
            y -= 1
        elif table[x][y] == "<": 
            y += 1
        elif table[x][y] == "^": 
            x -= 1

        # If it went out of bounds, return -1
        if y < 0 or y >= m or x < 0 or x >= n or (x, y) in visited:
            return -1

        # Check visited
        if x == n + 1:
            break

        visited.add((x, y))
        queue.append((x, y))

    return position


