def create_routines(target):
    routine = []
    for i in range(len(target)):
        if target[i] == 0:
            routine += [i] * i
        else:
            routine += [[i, j] for j in range(max(1, i - target[i] - 1), i + 1)]
    return routine

def find_path(target):
    frontiers = {i: (0, 0) for i in range(len(target))}
    queue = [(0, 0, -1, -1)]
    while queue:
        dist, c, w, b = queue.pop()
        if len(set(w)) == len(w):
            if len(w) == frontiers[c]:
                c += 1
            elif c not in frontiers:
                frontiers[c] = frontiers[c - 1]
            frontiers[c] += 1
        else:
            for i in set(w):
                queue.append((dist + 1, i + 1, c, b) if b == i else (dist + 1, c, i + 1, b))
    pack_info = []
    for i, j in sorted(frontiers.items(), key=lambda kv: -kv[1]):
        for k in [k for k in range(j, len(target)) if target[i] == k - i and (k - 1) in (j, i + 1)]:
            pack_info.append(k)
            break
    return pack_info

