from collections import defaultdict

def find_sets(edges):
    parent = list(range(len(edges) + 1))
    rank = [0] * (len(edges) + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        xr = find(x)
        yr = find(y)
        if xr != yr:
            if rank[xr] < rank[yr]:
                parent[xr] = yr
            elif rank[xr] > rank[yr]:
                parent[yr] = xr
            else:
                parent[yr] = xr
                rank[xr] += 1

    for edge in edges:
        union(edge[0], edge[1])

    sets = defaultdict(list)
    for i, parent_i in enumerate(parent):
        sets[find(parent_i)].append(i)
    return sets

