from collections import defaultdict, deque

def sort_vectors(n, rank, orders):
    rank = sorted(list(rank))
    adj_list = defaultdict(lambda: deque())

    for start, end in orders:
        adj_list[start].append(end)

    sorted_rank = rank
    seen = set()
    work_queue = rank[0].copy()

    while len(rank) > 0 and work_queue:
        rank_queue = work_queue.copy()
        order = []
        for person in work_queue:
            if person not in seen:
                seen.add(person)
                order.append(person)
                if order == rank:
                    return [-1]
                for mut in adj_list[person]:
                    if mut not in seen:
                        rank_queue.append(mut)
            else:
                rank_queue.popleft()

        work_queue = rank_queue

    return order

def solve(n, m, k, rank, orders):
    result = [-1 for _ in range(n)]
    rank_vector = sorted(list(rank))

    if len(rank) == n:
        return result

    for rank_index, rank in enumerate(rank_vector):
        if rank == -1:
            continue
        elif rank == 1:
            result[rank_index] = rank_vector[0]
        elif rank_index + rank == k:
            result[rank_index] = rank_vector[k - 1]
        else:
            result[rank_index] = 1

    for (start, end) in orders:
        if start in rank and end not in rank:
            if start >= end and start + end <= k - 1 or start + end > k - 1:
                result[start] = 1
                result[end] = 1

    for i in range(n):
        for back in rank[i:]:
            result[i] = min(result[i], back)

    for i in range(len(result)):
        if result[i] == -1:
            continue
        for front in rank[i:]:
            if front < result[i]:
                result[i] = front
                break

    for i in range(len(result)):
        if result[i] == -1:
            return [-1]

    return result

