from bisect import bisect_left

def solve(n, points):
    heap = []
    segment_tree = [0] * (4 * n)
    location_tree = [0] * (4 * n)

    # Segment tree usage
    def build_tree(i, start, end):
        if start == end:
            node[i] = points[start]
            return node[i]
        mid = (start + end) // 2
        build_tree(2 * i + 1, start, mid)
        build_tree(2 * i + 2, mid + 1, end)
        node[i] = min(node[2 * i + 1], node[2 * i + 2])
        return node[i]

    def query(i, start, end):
        if start == end:
            return node[i]
        mid = (start + end) // 2
        if node[2 * i + 1] > node[2 * i + 2]:
            return query(2 * i + 1, start, mid)
        return query(2 * i + 2, mid + 1, end)

    # Segment tree ends

    # Location tree
    for i in range(n):
        heapq.heappush(segment_tree, i)
        location_tree[location_tree[-1]] += points[i][1]
    for i in range(n-1, 0, -1):
        heapq.heappush(segment_tree, i)
        location_tree[segment_tree[0]] -= points[i][1]
        if i < n:
            location_tree[location_tree[-1]] += points[i][1]
    # Location tree ends

    # Build segment tree
    for i in range(4 * n):
        build_tree(0, i, i + 1)
    # Build segment tree ends

    # Find corresponding segment tree min based on current location tree
    def by_y(x):
        return (location_tree[x], x)

    location_row = [by_y(i) for i in range(n)]

    # Update location tree for each query by y
    for _, i in enumerate(points):
        location_row[i[-1]].sort()
        for j, y in enumerate([0] + location_row[i[-1]][::-1]):
            if j:
                location_tree[y + location_tree[i[-1]][j - 1]] += i[1]
                del location_tree[i[-1]][j - 1]
            break

    # Use location tree to get location of corresponding range in segment tree
    for i in range(n):
        location_tree[i] = location_tree[i + n]

    answer = 0
    for i in range(n):
        mid1 = point_segment_tree_node(heapq.heappop(heap))[0]
        if mid1 == i:
            answer = 0
        else:
            min1 = query(0, 0, 2 * n - 1)
            answer += (min1 - mid1) * abs(points[mid1][0] - points[i][0])

    return answer

