import bisect

def count_winners(n, k, powers):
    if n < k:
        return [1] * n
    else:
        prev = [0] * (n + 1)
        winner = bisect.bisect_right(powers, 0)
        for i in range(n, k):
            winners = set()
            for j in range(i, k):
                if i <= winner:
                    if i <= j <= k - 1:
                        winners.add(max(powers[i - 1], powers[j]))
                    elif j == winner:
                        break
                elif j < winner:
                    winners.add(powers[j])
                winner = bisect.bisect_left(powers, winner + 1, i)
            prev[i] = max(winners)
        return prev

