from collections import defaultdict

def find_parent(parent, node):
    if node != parent[node]:
        parent[node] = find_parent(parent, parent[node])
    return parent[node]

def make_union(parent, rank, x, y):
    xroot = find_parent(parent, x)
    yroot = find_parent(parent, y)

    if xroot == yroot:
        return False
    if rank[xroot] < rank[yroot]:
        xroot, yroot = yroot, xroot
    if rank[xroot] == rank[yroot]:
        rank[xroot] += 1
    parent[yroot] = xroot
    return True

def del_bad_edges(trees, change, new_nodes):
    parent = defaultdict(int)
    rank = defaultdict(int)
    for i in range(len(trees) - 1):
        parent[i] = i
    rank = [0] * (len(trees) - 1)
    edges = set()
    for i in trees[0]:
        edges.add(i)
    for i in new_nodes[change - 1]:
        edges.add(i)
    result = []
    current_edges = set(edges)
    edges = list(current_edges)
    local_edges = set()
    for i in trees[1]:
        local_edges.add(i - 1)
    for i in range(len(edges)):
        parent[edges[i]] = edges[i]
        rank[edges[i]] = 0
        current_edges.remove(edges[i])
    append = {}
    while len(current_edges) > 0:
        new_edges = []
        for i in trees[0]:
            x, y = find_parent(parent, i), find_parent(parent, edges[i])
            if not make_union(parent, rank, x, y):
                new_edges = set(edges) - local_edges
                continue
            x1, y2 = True, True
            if i < len(trees[0]):
                append[x] = y
                local_edges.add(i)
            for j in append.keys():
                if find_parent(parent, i) != find_parent(parent, j):
                    x1, y2 = True, True
                else:
                    x1 = False
                    y2 = False
            for j in append.keys():
                if append[j] in local_edges:
                    x1, y2 = True, True
            curr_exists = any(str(x1).lower() in str(company).lower() or str(y2).lower() in str(company).lower() for company in new_nodes)
            if curr_exists:
                new_edges = set(edges) - local_edges
                continue
            if i < len(trees[0]):
                local_edges.add(i - 1)
            local_edges |= set(append.values())
            new_edges |= set(append.keys())
            for edge in new_edges:
                if edge + 1 > len(new_nodes[change - 1]):
                    local_edges.remove(edge + 1)
            for parent_node in [x, y]:
                for edge in trees[change - 1]:
                    if edge + 1 <= len(new_nodes[change - 1]) and edge + 1 != find_parent(parent, edge):
                        current_edges.add(edge)
            current_edges -= new_edges
        for i in curr_edges:
            if find_parent(parent, i) == find_parent(parent, edges[i]):
                local_edges.remove(i)
        for edge in new_edges:
            if i + 1 <= len(trees[0]) and i + 1 != find_parent(parent, edges[i]):
                edges.add(i + 1)
        for company in new_nodes:
            if len(append) == 0:
                break
            if company[edges[-1]] == company[edges[-1] - 1]:
                for e in new_nodes:
                    if e[edges[-1]] == company[edges[-1]] and e[edges[-1] - 1] not in local_edges:
                        local_edges.add(e[edges[-1] - 1])
        for i in edges:
            local_edges |= set(append.values())
        result.append("Red\n" + " ".join(map(str, new_edges)))
        edges = new_edges
    return result

def check(trees, change, new_nodes):
    result = del_bad_edges(trees, change, new_nodes)
    return result

