from functools import lru_cache

def count_combinations(b, n):
    mod = 10**9 + 7
    dp = [[0] * (n + 1) for _ in range(b + 1)]
    dp[0] = 1

    for bag_size in range(1, n + 1):
        for bag in range(b + 1):
            for choice in range(min(bag, bag_size)):
                dp[bag] += dp[bag - choice]
                dp[bag][bag_size] += dp[bag - 1][bag - choice]
                dp[bag][bag_size] %= mod

    return dp[b][n]

