from heapq import heappush, heappop

def maximize_sum_of_squared_distances(n, r):
    max_sum = 0
    points = [(0, 0)]
    distances = []

    for i in range(n):
        candidate_pos = (0, r - 1 - i)
        while candidate_pos in points:
            candidate_pos = (0, r - 1 - i)
        points.append(candidate_pos)
        heappush(distances, -candidate_pos[0] ** 2 - candidate_pos[1] ** 2)

        if len(points) - 1 > 0:
            greatest_dist = 0
            largest_point1 = 0
            largest_point2 = 0
            for point1 in points:
                if len(points) > 1:
                    possible_next_pos = [candidate_pos[0], point1[1]]
                else:
                    possible_next_pos = [-candidate_pos[0], -candidate_pos[1]]
                for point2 in points:
                    if len(points) - 2 > 0:
                        possible_next_pos = [min(candidate_pos[0], point2[0]), max(candidate_pos[1], point2[1])]
                for dist_squared in distances:
                    dist = -dist_squared
                    next_node_pos = tuple(possible_next_pos)
                    if not next_node_pos in points:
                        if dist > greatest_dist:
                            greatest_dist = dist
                            largest_point1 = point1
                            largest_point2 = next_node_pos
            heappop(distances)
            heappush(distances, -greatest_dist)
            points.append(largest_point1)
            points.append(largest_point2)
        else:
            largest_plus_min_plus_dist = (r * r) ** 2
            max_sum = max(max_sum, largest_plus_min_plus_dist)

    return max_sum

print(maximize_sum_of_squared_distances(4, 1))
