def find_profile(mask):
    n = len(mask)
    row = [0] * (n + 1)
    for i in range(n):
        row[i] = mask[i]
    row[-1] = 0

    stack = []
    profile = []
    for i in range(n):
        while stack and (not row[i - 1] or row[i] > 0):
            stack.pop()
        if not stack:
            return -1
        profile.append(i - stack[-1])
        stack.append(i)

    if stack:
        while stack:
            profile.append(n - stack.pop())

    if not profile:
        return -1

    return profile

