def tournament_winner(competitions, powers):
    n = len(competitions)
    k = len(powers[0])
    dp = [1] + [0] * (2**k - 1)  # Initialize DP table with -1 and 1

    for i in range(1, 1 << k):
        j, j_sum = -1, 0
        for j2, p in enumerate(powers):
            if j & (1 << j2):
                if j_sum % 2:
                    j2, j_sum = -1, -1
                    break
                j_sum += p
                if j_sum > 0 and j2 > j2_sum:
                    j, j_sum = j2, j_sum
            elif j2 > j2_sum:
                j2_sum = j2
                j_sum = p
        dp[j] = i
        if j == -1:
            break

    winners = [0] * n
    for j, p in enumerate(powers):
        if p > 0 and dp[j] > -1:
            winners[dp[j]] += 1

    return winners

