from collections import defaultdict

def solve(n, m, k, ranks, orders):
    if k <= m:
        return '-1' if max(ranks) == m else ''.join([str(i+1) for i in sorted(ranks)])

    adj_matrix = defaultdict(list)
    for x, y in orders:
        adj_matrix[x-1].append(y-1)
        adj_matrix[y-1].append(x-1)

    visited = [False]*n
    for rank in ranks:
        if rank == 0:
            for x in range(n):
                if not visited[x]:
                    visited[x] = True
                    break

    result = [0]*n

    if sum(1 for rank in ranks if rank != 0) > m:
        return '-1'

    for j in range(n):
        if not visited[j]:
            result[j] = rank
            for neighbor in adj_matrix[j]:
                visited[neighbor] = True

    return ' '.join([str(r) for r in result])

# Example test cases
