def find_good_solution(n, L):
    if n == 1:
        return "!"

    i = 0
    next_i = 1
    l_range = [0 for _ in range(n)]
    next_l = 1

    while next_i < n:
        if next_i % 2 == 0:
            # Function is decreasing
            if L % (L // (next_i + 1)) == 0:
                l_range[i] = L // n
                next_i += next_i
            elif next_l == 10**18:
                # Large value reached
                break
            else:
                next_l += next_l
                l_range[i] = next_l - 1
                next_i += next_i
        else:
            # Function is increasing
            if L % (L // (next_i + 1)) == 0:
                l_range[i] = 0
                next_i += next_i
            else:
                next_l += next_l
                l_range[i] = next_l
                next_i += next_i

        if next_i >= n:
            break

        next_l = next_range = next_l + L // (n - next_i)
        next_i += 2 * (n - next_i)

    l_range.append(next_l)
    return " ".join(map(str, l_range))


# Example usage
