    max_x = len(board[0])
    visited_seats = set()

    def get_neighbours(pos):
        for x in range(pos[0] - 1, pos[0] + 2):
            for y in range(pos[1] - 1, pos[1] + 2):
                if (x, y) not in visited_seats and 0 <= x < max_x and 0 <= y < max_y:
                    yield (x, y)

    while changes:
        change_types = set()
        for change_idx, (curr_x, curr_y, prev_type) in enumerate(changes):
            new_type = shift_seat(Seat((curr_x, curr_y), prev_type))
            change_types.add(curr_type := new_type)
