def binary_search(n, L, MAX_VAL):
    def f(x, f):
        return sum(f[i] - f[i-1] for i in range(1, n+1) if x >= i)

    left = 0
    right = MAX_VAL

    while left < right:
        mid = (left + right) // 2
        if f(mid, range(n)) >= L / n:
            right = mid
        else:
            left = mid + 1

    return left

def lattice_paths(n, lattice_point_value):
