import sys

class FunctionGame:
    def __init__(self, n, L):
        self.n = n
        self.L = L
        self.available_queries = 0

    def ask_function_value(self, i, x):
        query = f"? {i} {x}\n"
        sys.stdout.write(query)
        sys.stdout.flush()
        return int(input())

    def find_segment(self, i):
        l = 0
        r = self.L
        while l < r:
            mid = (l + r) // 2
            if self.ask_function_value(i, mid) >= self.L / self.n:
                l = mid + 1
            else:
                r = mid
        return l

    def solve(self):
        solutions = []
        for i in range(1, self.n + 1):
            l = self.find_segment(i)
            if l < self.L:
                l += 1
            solutions.append((l, l + self.L))
        return solutions

